<script setup lang="ts">
import {localize} from './localization';

import {ref,computed,watch} from 'vue';
import {useSession} from './store';
import {resolvePiece} from '../../../packages/manufacturing/material';
import type {Piece} from '../../../packages/schema/index';
const props=defineProps<{piece:Piece;nodeId:string;language:'zh'|'en'}>(),emit=defineEmits<{jobs:[]}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const edges=computed(()=>[props.piece.nodes,...props.piece.holes??[]].flatMap((r,k)=>r.map((a,i)=>({a,b:r[(i+1)%r.length],label:(k?(zh.value?'孔 ':localize('Hole '))+k:(zh.value?'外环':localize('Outer')))+' / '+(i+1)})))),edgeId=ref(''),samples=ref([{s:0,widthMm:10},{s:1,widthMm:10}]),source=ref<'piece'|'material'|'project'>('piece'),mode=ref('constant'),width=ref(10);
const effective=computed(()=>store.data.project?resolvePiece(store.data.project,props.piece).allowanceMm:props.piece.allowanceMm),edge=computed(()=>edges.value.find(e=>e.a.id===edgeId.value));
watch(()=>props.nodeId,id=>{if(edges.value.some(e=>e.a.id===id))edgeId.value=id;});
watch(()=>JSON.stringify([props.piece.id,props.piece.allowanceSource]),()=>{const p=props.piece;if(!edges.value.some(e=>e.a.id===edgeId.value))edgeId.value=edges.value[0]?.a.id??'';source.value=p.allowanceSource??'piece';},{immediate:true});
watch(()=>JSON.stringify([props.piece.id,edge.value,props.piece.edgeAllowances,effective.value]),()=>{const p=props.piece.edgeAllowances?.find(e=>e.nodeId===edgeId.value);samples.value=p?JSON.parse(JSON.stringify(p.samples)):[{s:0,widthMm:effective.value},{s:1,widthMm:effective.value}];width.value=samples.value[0].widthMm;mode.value=samples.value.every(v=>v.widthMm===width.value)?'constant':'variable';},{immediate:true});
async function candidate(remove=false){const p=store.data.project,e=edge.value;if(!p||!e)return;const next=(props.piece.edgeAllowances??[]).filter(v=>v.nodeId!==e.a.id);if(!remove)next.push({nodeId:e.a.id,endNodeId:e.b.id,samples:mode.value==='constant'?[{s:0,widthMm:width.value},{s:1,widthMm:width.value}]:JSON.parse(JSON.stringify(samples.value))});if(await store.run(()=>window.fpcad.allowance(p.id,p.revision,props.piece.id,next,source.value)))emit('jobs');}
function add(){samples.value.splice(samples.value.length-1,0,{s:(samples.value[samples.value.length-2].s+1)/2,widthMm:samples.value.at(-1)!.widthMm});}
</script>
<template><details class="allowance-profile"><summary>{{zh?'逐边与可变缝份':localize('Per-edge and variable allowance')}}</summary><p>{{zh?'从缝线计算候选；采用后才保存。优先级：逐边采样 > 所选默认来源。s 为该边归一化弧长，必须递增并覆盖 0～1。':localize('Computed from the seam as a candidate. Edge samples override the chosen default. s is normalized arc length, increasing from 0 to 1.')}}</p><label>{{zh?'默认来源':localize('Default source')}}<select v-model="source"><option value="piece">{{zh?'当前纸样':localize('Piece')}}</option><option value="material">{{zh?'关联材料':localize('Linked material')}}</option><option value="project">{{zh?'项目默认':localize('Project default')}}</option></select></label><small>{{zh?'当前有效默认':localize('Effective default')}}: {{effective}} mm</small><label>{{zh?'边':localize('Edge')}}<select v-model="edgeId"><option v-for="e in edges" :key="e.a.id" :value="e.a.id">{{e.label}}</option></select></label><select v-model="mode"><option value="constant">{{zh?'逐边固定宽度':localize('Constant edge width')}}</option><option value="variable">{{zh?'沿弧长线性变化':localize('Linear arc-length profile')}}</option></select><label v-if="mode==='constant'">mm<input v-model.number="width" type="number" min="0" max="1000" step=".5"></label><template v-else><div v-for="(v,i) in samples" :key="i" class="two-col"><label>s<input v-model.number="v.s" type="number" min="0" max="1" step=".01" :disabled="i===0||i===samples.length-1"></label><label>mm<input v-model.number="v.widthMm" type="number" min="0" max="1000" step=".5"></label><button v-if="i>0&&i<samples.length-1" @click="samples.splice(i,1)">×</button></div><button :disabled="samples.length>=64" @click="add">{{zh?'增加采样点':localize('Add sample')}}</button></template><button :disabled="store.busy||!edge" @click="candidate()">{{zh?'计算逐边缝份候选':localize('Compute edge allowance candidate')}}</button><button :disabled="store.busy||!edge" @click="candidate(true)">{{zh?'移除边覆盖并计算候选':localize('Remove edge override and compute')}}</button><small>{{piece.edgeAllowances?.length??0}} {{zh?'条已采用边覆盖':localize('accepted edge overrides')}}</small></details></template>
<style scoped>details{border-top:1px solid var(--border);padding-top:12px;margin-top:12px}summary{cursor:pointer;font-weight:600}p,small{font-size:11px;line-height:1.5}button,select{width:100%;margin:4px 0}.two-col button{width:auto}</style>
